import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [h] = lines[0].split(" ").map(Number);

let bestRow = 1;
let bestCount = -1;
for (let i = 0; i < h; i++) {
  const row = lines[i + 1];
  let count = 0;
  for (const c of row) if (c === "#") count++;
  if (count > bestCount) {
    bestCount = count;
    bestRow = i + 1;
  }
}
console.log(bestRow + " " + bestCount);
